Graph shape: root -> MindIsland -> EmotionalEntity -> InteractionEvent
                                   EmotionalEntity -> ValueAction
"""

node MindIsland {
    has name: str = "Mind Island";
}

node EmotionalEntity {
    has label: str = "";
    has emotion: str = "";
    has intensity: int = 1;
    has shape: str = "stone";
    has color: str = "#9ca3af";
    has placed: bool = False;
    has x: int = 0;
    has y: int = 0;
    has note: str = "";
}

node InteractionEvent {
    has kind: str = "";
    has result: str = "";
}

node ValueAction {
    has value: str = "";
    has action: str = "";
}

glob INTERACTIONS: list[str] = ["breathe", "name", "soften", "listen"];

glob CRISIS_TERMS: list[str] = [
    "suicide", "suicidal", "kill myself", "end my life", "want to die",
    "hurt myself", "self harm", "self-harm", "no reason to live", "better off dead"
];

glob CRISIS_MESSAGE: str = "It sounds like you may be in danger right now. Please reach out for support immediately: call or text 988 (Suicide and Crisis Lifeline, US), call your local emergency number, or contact someone you trust and tell them how you feel. You do not have to go through this alone.";

glob EMOTION_TABLE: list[dict] = [
    {"emotion": "anxiety", "label": "Anxious cloud", "shape": "cloud", "color": "#c7d2fe", "keywords": ["anxious", "anxiety", "worried", "worry", "nervous", "stressed", "stress", "overwhelmed"]},
    {"emotion": "sadness", "label": "Heavy stone", "shape": "stone", "color": "#93c5fd", "keywords": ["sad", "down", "lonely", "alone", "empty", "grief", "cry", "hopeless"]},
    {"emotion": "anger", "label": "Hot ember", "shape": "ember", "color": "#fca5a5", "keywords": ["angry", "anger", "mad", "furious", "annoyed", "frustrated", "irritated"]},
    {"emotion": "fear", "label": "Shadow", "shape": "shadow", "color": "#d4d4d8", "keywords": ["afraid", "scared", "fear", "terrified", "panic"]},
    {"emotion": "tiredness", "label": "Drifting log", "shape": "log", "color": "#d6c4a8", "keywords": ["tired", "exhausted", "drained", "burnt out", "burned out", "sleepy"]},
    {"emotion": "joy", "label": "Bright flower", "shape": "flower", "color": "#fde68a", "keywords": ["happy", "glad", "joy", "excited", "grateful", "calm", "hopeful"]}
];

glob INTERACTION_RESULTS: dict = {
    "breathe": "You took three slow breaths with this feeling beside you.",
    "name": "You named the feeling out loud. Naming it gives it a shape you can hold.",
    "soften": "You let your shoulders drop. The feeling grew a little lighter.",
    "listen": "You asked the feeling what it needs and listened without judging."
};

"""True when the text contains urgent / crisis language."""
def is_crisis(text: str) -> bool {
    t = text.lower();
    for term in CRISIS_TERMS {
        if term in t {
            return True;
        }
    }
    return False;
}

"""Deterministic keyword mapping from free text to feeling specs."""
def detect_emotions(text: str) -> list[dict] {
    t = text.lower();
    intensity = 1;
    for amp in ["very", "so ", "really", "extremely", "too "] {
        if amp in t {
            intensity = intensity + 1;
        }
    }
    if intensity > 3 {
        intensity = 3;
    }
    found: list[dict] = [];
    for spec in EMOTION_TABLE {
        for kw in spec["keywords"] {
            if kw in t {
                found.append({
                    "emotion": spec["emotion"],
                    "label": spec["label"],
                    "shape": spec["shape"],
                    "color": spec["color"],
                    "intensity": intensity
                });
                break;
            }
        }
    }
    if len(found) == 0 {
        found.append({
            "emotion": "unnamed",
            "label": "Unnamed pebble",
            "shape": "pebble",
            "color": "#cbd5e1",
            "intensity": intensity
        });
    }
    return found;
}

"""Plain dict projection of an entity for the client."""
def entity_view(e: EmotionalEntity) -> dict {
    return {
        "id": jid(e),
        "label": e.label,
        "emotion": e.emotion,
        "intensity": e.intensity,
        "shape": e.shape,
        "color": e.color,
        "placed": e.placed,
        "x": e.x,
        "y": e.y,
        "note": e.note
    };
}

"""Get-or-create the island attached to the given root."""
def get_island(r: Root) -> MindIsland {
    islands = [r -->[?:MindIsland]];
    if len(islands) > 0 {
        return islands[0];
    }
    island = MindIsland();
    r ++> island;
    return island;
}

"""Resolve an entity id to an EmotionalEntity, or None."""
def find_entity(entity_id: str) -> EmotionalEntity | None {
    if not entity_id {
        return None;
    }
    try {
        obj = jobj(entity_id);
    } except Exception {
        return None;
    }
    if isinstance(obj, EmotionalEntity) {
        return obj;
    }
    return None;
}

def clamp(v: int) -> int {
    if v < 5 {
        return 5;
    }
    if v > 95 {
        return 95;
    }
    return v;
}

walker:pub get_world {
    has reports: list[dict] = [];

    can run with Root entry {
        island = get_island(here);
        entities = [island -->[?:EmotionalEntity]];
        report {
            "entities": [entity_view(e) for e in entities],
            "interactions": INTERACTIONS
        };
    }
}

walker:pub manifest_emotion {
    has text: str = "";
    has reports: list[dict] = [];

    can run with Root entry {
        t = self.text.strip();
        if not t {
            report {"crisis": False, "error": "Describe how you feel first.", "message": "", "entities": []};
            disengage;
        }
        if is_crisis(t) {
            report {"crisis": True, "message": CRISIS_MESSAGE, "entities": []};
            disengage;
        }
        island = get_island(here);
        created: list[dict] = [];
        for spec in detect_emotions(t) {
            e = EmotionalEntity(
                label=spec["label"],
                emotion=spec["emotion"],
                intensity=spec["intensity"],
                shape=spec["shape"],
                color=spec["color"],
                note=t
            );
            island ++> e;
            created.append(entity_view(e));
        }
        report {"crisis": False, "message": "", "entities": created};
    }
}

walker:pub place_entity {
    has entity_id: str = "";
    has x: int = 0;
    has y: int = 0;
    has reports: list[dict] = [];

    can run with Root entry {
        e = find_entity(self.entity_id);
        if e is None {
            report {"error": "Feeling not found."};
            disengage;
        }
        e.placed = True;
        e.x = clamp(self.x);
        e.y = clamp(self.y);
        report {"entity": entity_view(e)};
    }
}

walker:pub apply_interaction {
    has entity_id: str = "";
    has kind: str = "";
    has reports: list[dict] = [];

    can run with Root entry {
        e = find_entity(self.entity_id);
        if e is None {
            report {"error": "Feeling not found."};
            disengage;
        }
        if not e.placed {
            report {"error": "Place the feeling on the island first."};
            disengage;
        }
        if self.kind not in INTERACTIONS {
            report {"error": "Unknown interaction."};
            disengage;
        }
        if self.kind == "soften" and e.intensity > 1 {
            e.intensity = e.intensity - 1;
        }
        result = INTERACTION_RESULTS[self.kind];
        ev = InteractionEvent(kind=self.kind, result=result);
        e ++> ev;
        report {"entity": entity_view(e), "event": {"kind": ev.kind, "result": ev.result}};
    }
}

walker:pub commit_value_action {
    has entity_id: str = "";
    has value: str = "";
    has action: str = "";
    has reports: list[dict] = [];

    can run with Root entry {
        e = find_entity(self.entity_id);
        if e is None {
            report {"error": "Feeling not found."};
            disengage;
        }
        if not e.placed {
            report {"error": "Place the feeling on the island first."};
            disengage;
        }
        v = self.value.strip();
        a = self.action.strip();
        if not v or not a {
            report {"error": "Add both what matters to you and one concrete next action."};
            disengage;
        }
        va = ValueAction(value=v, action=a);
        e ++> va;
        report {"entity": entity_view(e), "action": {"value": va.value, "action": va.action}};
    }
}

walker:pub get_act_path {
    has entity_id: str = "";
    has reports: list[dict] = [];

    can run with Root entry {
        e = find_entity(self.entity_id);
        if e is None {
            report {"error": "Feeling not found."};
            disengage;
        }
        events = [e -->[?:InteractionEvent]];
        actions = [e -->[?:ValueAction]];
        report {
            "entity": entity_view(e),
            "events": [{"kind": ev.kind, "result": ev.result} for ev in events],
            "actions": [{"value": va.value, "action": va.action} for va in actions]
        };
    }
}

walker:pub reset_demo {
    has reports: list[dict] = [];

    can run with Root entry {
        island = get_island(here);
        entities = [island -->[?:EmotionalEntity]];
        cleared = len(entities);
        for e in entities {
            for ev in [e -->[?:InteractionEvent]] {
                del ev;
            }
            for va in [e -->[?:ValueAction]] {
                del va;
            }
            del e;
        }
        report {"cleared": cleared};
    }
}
