        def on_action(e: ChangeEvent) { action = e.target.value; }

        pending = [en for en in entities if not en["placed"]];
        placed = [en for en in entities if en["placed"]];
        selected: dict | None = None;
        for en in entities {
            if en["id"] == selectedId {
                selected = en;
            }
        }
        selected_placed: bool = selected is not None and selected["placed"];

        return <main className="mc-shell">
            <header className="mc-header">
                <h1>Mindcraft</h1>
                <p>Name how you feel, give it a place on your island, and choose one gentle next step.</p>
            </header>
            {crisisMsg and <div className="mc-crisis" role="alert">
                <strong>You deserve support right now.</strong>
                <p>{crisisMsg}</p>
            </div>}
            <div className="mc-grid">
                <section className="mc-card">
                    <div className="mc-row" style={{"justifyContent": "space-between", "alignItems": "center"}}>
                        <h2>Your island</h2>
                        <button className="mc-btn" onClick={lambda { reset(); }}>Reset island</button>
                    </div>
                    <div className="mc-island" data-testid="island">
                        {if loading {
                            <div className="mc-island-empty">Loading your island...</div>
                        } elif len(placed) == 0 {
                            <div className="mc-island-empty">
                                <strong>Your island is empty</strong>
                                <span>Check in below, then place a feeling here.</span>
                            </div>
                        }}
                        {for en in placed {
                            <button
                                key={en["id"]}
                                className={"mc-entity is-selected" if en["id"] == selectedId else "mc-entity"}
                                style={{"left": str(en["x"]) + "%", "top": str(en["y"]) + "%", "background": en["color"]}}
                                onClick={lambda { select(en["id"]); }}
                            >{en["label"] + " (" + str(en["intensity"]) + ")"}</button>
                        }}
                    </div>
                    <div className="mc-stack" style={{"marginTop": "12px"}}>
                        <span className="mc-label">Gentle interactions</span>
                        <div className="mc-row">
                            {for k in interactions {
                                <button key={k} className="mc-btn" disabled={not selected_placed} onClick={lambda { interact(k); }}>{k}</button>
                            }}
                        </div>
                        {if not selected_placed {
                            <span className="mc-muted">Select a placed feeling to try an interaction.</span>
                        }}
                    </div>
                </section>
                <aside className="mc-stack">
                    <section className="mc-card mc-stack">
                        <h2>Check in</h2>
                        <label className="mc-label" htmlFor="feel">How are you feeling?</label>
                        <textarea id="feel" className="mc-textarea" placeholder="I feel anxious about tomorrow and a bit tired" value={text} onChange={on_text} />
                        <button className="mc-btn mc-btn-primary" disabled={busy} onClick={lambda { check_in(); }}>Add check-in</button>
                        {error and <span className="mc-error">{error}</span>}
                        {notice and <span className="mc-muted">{notice}</span>}
                    </section>
                    <section className="mc-card mc-stack">
                        <h2>Waiting to be placed</h2>
                        {if len(pending) == 0 {
                            <span className="mc-muted">No pending feelings.</span>
                        }}
                        <div className="mc-pending">
                            {for (i, en) in enumerate(pending) {
                                <button key={en["id"]} className="mc-chip" onClick={lambda { place(en["id"], len(placed) + i); }}>{"Place " + en["label"]}</button>
                            }}
                        </div>
                    </section>
                    {selected_placed and <section className="mc-card mc-stack">
                        <h2>{"Next step for " + selected["label"]}</h2>
                        <label className="mc-label" htmlFor="val">What matters to you here?</label>
                        <input id="val" className="mc-input" placeholder="Being prepared" value={value} onChange={on_value} />
                        <label className="mc-label" htmlFor="act">One concrete next action</label>
                        <input id="act" className="mc-input" placeholder="Write three bullet points for tomorrow" value={action} onChange={on_action} />
                        <button className="mc-btn mc-btn-primary" onClick={lambda { commit(); }}>Commit intention</button>
                        <span className="mc-label">Path</span>
                        {if pathLoaded and len(pathEvents) == 0 and len(pathActions) == 0 {
                            <span className="mc-muted">Placed. No interactions or intentions yet.</span>
                        }}
                        <ol className="mc-path">
                            <li>{"Felt: " + selected["note"]}</li>
                            <li>Placed on the island</li>
                            {for (i, ev) in enumerate(pathEvents) {
                                <li key={"ev" + str(i)}>{"Tried " + ev["kind"] + ": " + ev["result"]}</li>
                            }}
                            {for (i, va) in enumerate(pathActions) {
                                <li key={"va" + str(i)}>{"Intention (" + va["value"] + "): " + va["action"]}</li>
                            }}
                        </ol>
                    </section>}
                </aside>
            </div>
        </main>;
    }
}
"}

