    def:pub MindcraftApp() -> JsxElement {
        has entities: list[dict] = [];
        has interactions: list[str] = [];
        has text: str = "";
        has crisisMsg: str = "";
        has selectedId: str = "";
        has value: str = "";
        has action: str = "";
        has pathEvents: list[dict] = [];
        has pathActions: list[dict] = [];
        has pathLoaded: bool = False;
        has notice: str = "";
        has error: str = "";
        has loading: bool = True;
        has busy: bool = False;

        async def load_world() -> None {
            try {
                result = root spawn get_world();
                if result.reports and len(result.reports) > 0 {
                    data = result.reports[0];
                    entities = data["entities"];
                    interactions = data["interactions"];
                }
            } except Exception as ex {
                error = "Could not load the island. Try refreshing.";
            }
            loading = False;
        }

        async can with entry {
            await load_world();
        }

        async def load_path(eid: str) -> None {
            result = root spawn get_act_path(entity_id=eid);
            if result.reports and len(result.reports) > 0 {
                data = result.reports[0];
                if data["error"] {
                    error = str(data["error"]);
                } else {
                    pathEvents = data["events"];
                    pathActions = data["actions"];
                    pathLoaded = True;
                }
            }
        }

        async def check_in() -> None {
            error = "";
            notice = "";
            crisisMsg = "";
            if not text.strip() {
                error = "Describe how you feel first.";
                return;
            }
            busy = True;
            result = root spawn manifest_emotion(text=text);
            if result.reports and len(result.reports) > 0 {
                data = result.reports[0];
                if data["crisis"] {
                    crisisMsg = str(data["message"]);
                } elif data["error"] {
                    error = str(data["error"]);
                } else {
                    notice = str(len(data["entities"])) + " feeling(s) arrived. Place them on the island.";
                    text = "";
                }
            }
            await load_world();
            busy = False;
        }

        async def select(eid: str) -> None {
            selectedId = eid;
            pathEvents = [];
            pathActions = [];
            pathLoaded = False;
            error = "";
            await load_path(eid);
        }

        async def place(eid: str, idx: int) -> None {
            error = "";
            px = 20 + (idx * 23) % 60;
            py = 30 + (idx * 17) % 40;
            result = root spawn place_entity(entity_id=eid, x=px, y=py);
            if result.reports and len(result.reports) > 0 {
                data = result.reports[0];
                if data["error"] {
                    error = str(data["error"]);
                }
            }
            selectedId = eid;
            await load_world();
            await load_path(eid);
        }

        async def interact(kind: str) -> None {
            error = "";
            result = root spawn apply_interaction(entity_id=selectedId, kind=kind);
            if result.reports and len(result.reports) > 0 {
                data = result.reports[0];
                if data["error"] {
                    error = str(data["error"]);
                } else {
                    notice = str(data["event"]["result"]);
                }
            }
            await load_world();
            await load_path(selectedId);
        }

        async def commit() -> None {
            error = "";
            result = root spawn commit_value_action(entity_id=selectedId, value=value, action=action);
            if result.reports and len(result.reports) > 0 {
                data = result.reports[0];
                if data["error"] {
                    error = str(data["error"]);
                } else {
                    notice = "Next action saved: " + str(data["action"]["action"]);
                    value = "";
                    action = "";
                }
            }
            await load_path(selectedId);
        }

        async def reset() -> None {
            error = "";
            crisisMsg = "";
            result = root spawn reset_demo();
            if result.reports and len(result.reports) > 0 {
                notice = "Island cleared (" + str(result.reports[0]["cleared"]) + " feeling(s) released).";
            }
            selectedId = "";
            pathEvents = [];
            pathActions = [];
            pathLoaded = False;
            await load_world();
        }

        def on_text(e: ChangeEvent) { text = e.target.value; }
        def on_value(e: ChangeEvent) { value = e.target.value; }
        def on_action(e: ChangeEvent) { action = e.target.value; }

        pending = [en for en in entities if not en["placed"]];
        placed = [en for en in entities if en["placed"]];
        selected: dict | None = None;
        for en in entities {
            if en["id"] == selectedId {
                selected = en;
            }
        }
        selected_placed: bool = selected is not None and selected["placed"];
        selected_label: str = str(selected["label"]) if selected is not None else "";
        selected_note: str = str(selected["note"]) if selected is not None else "";

        return <main className="mc-shell">
            <header className="mc-header">
                <h1>Mindcraft</h1>
                <p>Name how you feel, give it a place on your island, and choose one gentle next step.</p>
            </header>
            {crisisMsg and <div className="mc-crisis" role="alert">
                <strong>You deserve support right now.</strong>
                <p>{crisisMsg}</p>
            </div>}
            <div className="mc-grid">
                <section className="mc-card">
                    <div className="mc-row" style={{"justifyContent": "space-between", "alignItems": "center"}}>
                        <h2>Your island</h2>
                        <button className="mc-btn" onClick={lambda { reset(); }}>Reset island</button>
                    </div>
                    <div className="mc-island" data-testid="island">
                        {if loading {
                            <div className="mc-island-empty">Loading your island...</div>
                        } elif len(placed) == 0 {
                            <div className="mc-island-empty">
                                <strong>Your island is empty</strong>
                                <span>Check in below, then place a feeling here.</span>
                            </div>
                        }}
                        {for en in placed {
                            <button
                                key={str(en["id"])}
                                className={"mc-entity is-selected" if en["id"] == selectedId else "mc-entity"}
                                style={{"left": str(en["x"]) + "%", "top": str(en["y"]) + "%", "background": en["color"]}}
                                onClick={lambda { select(str(en["id"])); }}
                            >{str(en["label"]) + " (" + str(en["intensity"]) + ")"}</button>
                        }}
                    </div>
                    <div className="mc-stack" style={{"marginTop": "12px"}}>
                        <span className="mc-label">Gentle interactions</span>
                        <div className="mc-row">
                            {for k in interactions {
                                <button key={k} className="mc-btn" disabled={not selected_placed} onClick={lambda { interact(k); }}>{k}</button>
                            }}
                        </div>
                        {if not selected_placed {
                            <span className="mc-muted">Select a placed feeling to try an interaction.</span>
                        }}
                    </div>
                </section>
                <aside className="mc-stack">
                    <section className="mc-card mc-stack">
                        <h2>Check in</h2>
                        <label className="mc-label" htmlFor="feel">How are you feeling?</label>
                        <textarea id="feel" className="mc-textarea" placeholder="I feel anxious about tomorrow and a bit tired" value={text} onChange={on_text} />
                        <button className="mc-btn mc-btn-primary" disabled={busy} onClick={lambda { check_in(); }}>Add check-in</button>
                        {error and <span className="mc-error">{error}</span>}
                        {notice and <span className="mc-muted">{notice}</span>}
                    </section>
                    <section className="mc-card mc-stack">
                        <h2>Waiting to be placed</h2>
                        {if len(pending) == 0 {
                            <span className="mc-muted">No pending feelings.</span>
                        }}
                        <div className="mc-pending">
                            {for (i, en) in enumerate(pending) {
                                <button key={str(en["id"])} className="mc-chip" onClick={lambda { place(str(en["id"]), len(placed) + i); }}>{"Place " + str(en["label"])}</button>
                            }}
                        </div>
                    </section>
                    {selected_placed and <section className="mc-card mc-stack">
                        <h2>{"Next step for " + selected_label}</h2>
                        <label className="mc-label" htmlFor="val">What matters to you here?</label>
                        <input id="val" className="mc-input" placeholder="Being prepared" value={value} onChange={on_value} />
                        <label className="mc-label" htmlFor="act">One concrete next action</label>
                        <input id="act" className="mc-input" placeholder="Write three bullet points for tomorrow" value={action} onChange={on_action} />
                        <button className="mc-btn mc-btn-primary" onClick={lambda { commit(); }}>Commit intention</button>
                        <span className="mc-label">Path</span>
                        {if pathLoaded and len(pathEvents) == 0 and len(pathActions) == 0 {
                            <span className="mc-muted">Placed. No interactions or intentions yet.</span>
                        }}
                        <ol className="mc-path">
                            <li>{"Felt: " + selected_note}</li>
                            <li>Placed on the island</li>
                            {for (i, ev) in enumerate(pathEvents) {
                                <li key={"ev" + str(i)}>{"Tried " + str(ev["kind"]) + ": " + str(ev["result"])}</li>
                            }}
                            {for (i, va) in enumerate(pathActions) {
                                <li key={"va" + str(i)}>{"Intention (" + str(va["value"]) + "): " + str(va["action"])}</li>
                            }}
                        </ol>
                    </section>}
                </aside>
            </div>
        </main>;
    }
}
"}
